function mudOut(){ return Env.tide.lv < -0.35; }          // 泥灘露出來（伺服器抓的時候要更低：-0.5）
function mudGrabOk(){ return Env.tide.lv < -0.5; }
var Mang = { mud:[], mudY:-0.4, critters:[], told:0, flies:null, onMud:false };
