  const soil = mat('#9c9078', 0.95), grass = mat('#8fae6c', 0.95), mudM = mat('#a39880', 0.45, { emissive:'#3a3428', emissiveIntensity:0.06 });   /* 紅毛港的泥灘是灰色的 */
