function farmLocal(){ const d = LS.get('tide.farm', null) || { n:4, plots:[] }; return { n: d.n || 4, plots: Array.isArray(d.plots) ? d.plots : [], sea: { n: d.sn || 4, max: 16 }, deco: Array.isArray(d.deco) ? d.deco : [] }; }
