  ms = ms || Date.now(); const L = new Date(ms + 8 * 3600e3), day0 = Date.UTC(L.getUTCFullYear(), L.getUTCMonth(), L.getUTCDate()) - 8 * 3600e3, dur = TOURNEY.mins * 60e3;
