  for (const h of items0) if (Array.isArray(h.f)) for (const o of h.f) if (o && o.t === 'turtletank') pens.push({ indoor: true, hid: h.id, fid: o.id, t: 'turtletank', id: 'h' + h.id + 'f' + o.id, x: o.x, z: o.z, r: o.r });
