  let list = []; if (onIsle.owner === myIdOrMe()) list = (Pets.list || []).filter(p => !p.out && p.price == null); else if (Cloud.on){ try { const { data } = await Cloud.sb.rpc('isle_pets', { p_owner: onIsle.owner }); if (Array.isArray(data)) list = data; } catch(e){} }
