      const spot = () => { const u = (Math.random() * 2 - 1) * 1.0, v = (Math.random() * 2 - 1) * 0.48, c = Math.cos(fm.rotation.y), s = Math.sin(fm.rotation.y); return [fm.position.x + u * c + v * s, fm.position.z - u * s + v * c]; };
