const FEST_ICON = { xmas:'🎄', qixi:'💞', halloween:'🎃' };
const Fest = { d:null, at:0, busy:false, deco:{}, riddles:null, seen:{} };
function festTest(){ const m = /fest=(ny|cny|lantern|duanwu|moon|night|xmas|qixi|halloween)/.exec(location.hash); return m ? m[1] : null; }
