  if (F.phase !== 'idle'){ toast('正在釣魚，先收竿再炫耀吧'); return; }
  /* v272 只能炫耀現在還在你身邊的魚：魚缸裡的（展示中的也算），每一種挑最重的那條。賣掉、捐給博物館、交給阿鐵的就不算了 */
