  for (const x of rec.tank || []){ const f = FISH_BY_ID[x.f]; if (!f || !(x.w > 0)) continue; if (!top[x.f] || x.w > top[x.f].w) top[x.f] = x; }
  const ids = Object.keys(top);
  if (!ids.length){ toast('魚缸裡沒有魚可以炫耀，先去釣一條吧'); return; }
