    if (f.desc) card.appendChild(el('p', 'scis', f.desc)); card.appendChild(el('div', 'sub2', rec.count[f.id] ? `✅ 你一共釣過 ${rec.count[f.id]} 條` : '你還沒釣過這種魚')); body.appendChild(card);
