  const R = n.roam, P = R.post;
  if (!R.ready){ if (frameNo > 500 && frameNo % 4 === 0 && Math.hypot(camera.position.x - P.x, camera.position.z - P.z) < 110) roamGrow(n); return false; }   /* 等世界都蓋好（有些東西晚一點才放）再找去處 */
