  const cur = curBuff(); if (cur) P.appendChild(el('p', 'sub warn', `你現在還有 ${RECIPES[cur.r].icon}${RECIPES[cur.r].name} 的加成（剩 ${cur.left} 次），點新的會換掉。`));
